/** Synthetic fixed inputs exercise the exact isolated LIVE tools, without game data. */
import assert from 'node:assert/strict';
import {mkdtempSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {KnowledgeStore} from './src/knowledge/runtime/store.ts';
import {closeIndexedReaders} from './src/knowledge/runtime/reader.ts';
import {setKnowledgeCharacter} from './src/knowledge/files.ts';
import {buildKnowledgeTools} from './src/brain/tools/agent-knowledge.ts';
import {ToolHost} from './src/brain/tools/mcp-server.ts';

async function main() {
 const root = mkdtempSync(join(tmpdir(), 'issue78-live-fixed-'));
 const store = new KnowledgeStore(root);
 try {
  const strategy = {id:'oversized-strategy', version:'fixture', source:'own', confidence:.25,
   trigger:{question_types:['card_reward'], acts:[1], floor:{min:5,max:18}, deck_cards:[{name:'TEST_CARD',count:{min:1}}]},
   strategy:'格式测试正文，非游戏知识', evidence_status:'conflict', limits:['合成夹具，不能用于游戏'],
   evidence:[{run:'SILENT000001',floor:5,role:'support',ref:'格式证据😀"\\\n'.repeat(1000)},
    {run:'SILENT000002',floor:6,role:'contradict',ref:'反证保持'}]};
  const experience = {id:'oversized-experience',scope:'general:deck',asc:[0,20],lesson:'格式测试结论',status:'active',confidence:'low',
   n_support:1000,n_contradict:1,evidence:Array.from({length:1000},(_,i)=>`SYNTHETIC_${i}`),contradicting:['COUNTEREXAMPLE'],last_seen:'2026-10-26'};
  const reflex = {schema:'reflex-entry-v1',id:'test_reflex',version:1,applies_to:'card_pick',
   predicate:{op:'gte',field:'player.hp',value:10},signal:{kind:'hp',value:1,se:.2,unit:'hp'},label_en:'Test format only',
   evidence:{observations:Array.from({length:1000},(_,i)=>({run_id:`SYNTHETIC_${i}`,floor:8,turn:1})),n_support:1000,n_contradict:2},
   confidence:.5,scope:{character:'silent',ascensions:[0]},source_experience:['TEST_EXPERIENCE']};
  const files = {
   'characters/silent/strategy-entries.json':JSON.stringify({schema:'brain-strategies-v1',character:'silent',entries:[strategy]}),
   'characters/silent/experience.json':JSON.stringify({version:'fixture',entries:[experience]}),
   'characters/silent/reflex.json':JSON.stringify({schema:'reflex-file-v1',character:'silent',entries:[reflex]}),
  };
  store.submit({schema:'knowledge-candidate-v1',id:'fixture',base:null,character:'migration',source:'fixture',files});
  store.validate('fixture'); const version=store.publish('fixture');
  const snapshot=String(store.bind('FIXTURE','fixed-code').snapshot);
  setKnowledgeCharacter('silent');
  const ctx={knowledgeDir:snapshot,logsDir:snapshot,ascension:0,act:1,label:'reward/card',payload:{facts:{act:1,floor:10,deck:'TEST_CARD'}}};
  const host=new ToolHost(buildKnowledgeTools(ctx),ctx);
  const call=async(name,input)=>{
   const result=await host.call(name,input);
   assert(!result.isError,result.text);assert(Buffer.byteLength(result.text)<=24000);
   return JSON.parse(result.text);
  };
  const results=[];
  for(const [tool,input,original] of [
   ['kb_strategies',{query:strategy.id},strategy],['kb_experience',{id:experience.id},experience],['kb_reflex',{query:reflex.id},reflex],
  ]) {
   const projection=await call(tool,input);
   assert.equal(projection.returned,1);assert.equal(projection.oversized_skipped,0);
   assert.equal(projection.knowledge_version,version);
   assert.equal(projection.entries[0].id,original.id);assert.equal(projection.entries[0].confidence,original.confidence);
   if(tool==='kb_strategies') {
    assert.deepEqual(projection.entries[0].trigger,strategy.trigger);
    assert.equal(projection.entries[0].strategy,strategy.strategy);
    assert.equal(projection.entries[0].evidence_status,'conflict');
    assert(projection.entries[0].evidence.some(e=>e.role==='contradict'));
   }
   let offset=0,raw='',digest='',pages=0;
   while(offset!==null) {
    const p=await call(tool,{...input,detail:'full',document_id:original.id,document_offset:offset});
    assert.deepEqual(p.entries,[{id:original.id}]);assert.equal(p.document_offset,offset);
    digest ||= p.document_sha256;assert.equal(p.document_sha256,digest);
    raw+=p.json_fragment;offset=p.next_document_offset;assert(++pages<100);
   }
   assert.equal(createHash('sha256').update(raw).digest('hex'),digest);
   assert.deepEqual(JSON.parse(raw),original);
   results.push({tool,returned:1,pages,bytes:Buffer.byteLength(raw),roundtrip:true});
  }
  for(const facts of [{act:1,floor:25,deck:'TEST_CARD'},{act:1,floor:10,deck:'OTHER_CARD'}]) {
   ctx.payload={facts};
   for(const detail of ['projection','full']) assert.equal((await call('kb_strategies',{query:strategy.id,detail,...(detail==='full'?{document_id:strategy.id}:{})})).returned,0);
  }
  ctx.payload={facts:{act:1,floor:10,deck:'TEST_CARD'}};
  setKnowledgeCharacter('ironclad');
  assert.equal((await call('kb_strategies',{query:strategy.id,detail:'full',document_id:strategy.id})).returned,0);
  assert.deepEqual(store.files(version),files);
  console.log(JSON.stringify({scope:'isolated LIVE synthetic production ToolHost',results,negatives:true,source_files_unchanged:true}));
 } finally {closeIndexedReaders();setKnowledgeCharacter(null);store.close();rmSync(root,{recursive:true,force:true});}
}
main().catch(error=>{console.error(error);process.exitCode=1;});

/** Fixed synthetic deployment contract, never production knowledge or game data. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {mkdtempSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {KnowledgeStore} from './src/knowledge/runtime/store.ts';
import {KnowledgeReader, closeIndexedReaders} from './src/knowledge/runtime/reader.ts';
import {setKnowledgeCharacter} from './src/knowledge/files.ts';
import {DECISION_CONTEXT_FILE} from './src/knowledge/decision-context.ts';
import {attachDecisionKnowledge, decisionContextTool} from './src/brain/decision-knowledge.ts';
import {buildKnowledgeTools} from './src/brain/tools/agent-knowledge.ts';
import {ToolHost} from './src/brain/tools/mcp-server.ts';
import {loadConfig} from './src/core/config.ts';

const sha = (text) => createHash('sha256').update(text).digest('hex');
async function main() {
 const root = mkdtempSync(join(tmpdir(), 'issue81-72-live-fixed-'));
 const stores = [], readers = [];
 try {
  setKnowledgeCharacter('silent');
  const store = new KnowledgeStore(root); stores.push(store);
  const context = {id:'context-fixture', dimension:'格式', status:'active', triggers:['选牌'],
   conditions:{character:'silent', ascensions:[10], acts:[1], candidate_ids:['FIXTURE_CARD']},
   priority:50, summary:'格式夹具😀\\\"\n'.repeat(4000), rule_candidate:'仅测试，不是游戏知识', confidence:.25,
   denominators:{own_runs:0,external:{unit:'uploads',n:7},association_only:true},
   evidence_refs:[{type:'external_aggregate',source:'external:fixture',url:'https://example.com/fixture',
    version:'fixture-v1',downloaded_at:'2026-10-27',sha256:'a'.repeat(64),filters:'synthetic',denominator:{unit:'uploads',n:7},role:'support'}],
   counterexamples:[{id:'counter',n:1}],limitations:['合成夹具，不能用于游戏'],conflicts_with:[{id:'old-fixture',reason:'原反证'}],
   review_origin:{schema:'issue80-review-candidates-v1',id:'context-fixture',sha256:'b'.repeat(64),conditions:{observable_build:'不猜测原文条件'}}};
  const original = JSON.stringify({observation:'原始格式夹具，非游戏知识'});
  const research = {id:'research-fixture',revision:'fixture-r1',title:'格式研究',scope:{character:'silent',ascensions:[10],game_version:'fixture-v1'},
   source:'external:fixture',status:'candidate',confidence:.2,evidence_status:'conflict',verified_complete_playbook:false,validation_status:'unverified',
   sources:[{id:'source-a',source:'external:fixture',url:'https://example.org/fixture',game_version:'fixture-v1',sha256:'c'.repeat(64),
    downloaded_at:'2026-10-27',sample:{n:7,unit:'uploads',players:null},filters:'synthetic only',license:'synthetic fixture',design:'observational',limitations:['非随机样本']}],
   evidence:[{id:'support',source_id:'source-a',role:'support',ref:'synthetic:1',observation:'顺序甲乙',limitations:['unknown']},
    {id:'counter',source_id:'source-a',role:'contradict',ref:'synthetic:2',observation:'顺序乙甲',limitations:['unknown']}],
   phases:['START','BOSS1','TRANSITION','RESOURCE','FINAL'].map((stage,i)=>({id:`p${i}`,stage,acts:[Math.min(3,Math.floor(i/2)+1)],
    goals:[`goal-${i}`],evidence_ids:['support','counter'],content:{condition:('格式观测😀\\\"\n').repeat(i===0?6000:1),unknown:'缺实际状态'}})),
   limitations:['外部观察，不估计收益'],unknowns:['真实战前状态'],original:{sha256:sha(original),content:original},references:[]};
  const researchFile = 'characters/silent/build-research.json';
  const files = {[DECISION_CONTEXT_FILE]:JSON.stringify({schema:'decision-context-v1',character:'silent',status:'published',entries:[context]}),
   [researchFile]:JSON.stringify({schema:'build-research-v1',character:'silent',entries:[research]})};
  store.submit({schema:'knowledge-candidate-v1',id:'fixture-first',base:null,character:'silent',source:'fixture',files});
  store.validate('fixture-first'); const version=store.publish('fixture-first');
  const directory=String(store.bind('FIXTURE','fixture-code').snapshot);
  const ctx={label:'reward/card',knowledgeDir:directory,logsDir:root,ascension:10,act:1,payload:{facts:{act:1,floor:3}},
   state:{game_version:'fixture-v1',run:{character_id:'SILENT',act_id:0,floor:3},reward:{card_options:[{card_id:'FIXTURE_CARD'}]}}};
  const req={label:'reward/card',system:'fixed',question:'fixed',payload:ctx.payload,options:{a:null},toolContext:ctx,knowledge:{mode:'tools'}};
  const config=loadConfig({}).brain.decisionKnowledge;
  assert.deepEqual(config,{enabled:false,bytes:8000}); assert.equal(attachDecisionKnowledge(req),req);
  const render=()=>attachDecisionKnowledge(req,{enabled:true,bytes:8000}).payload.decision_knowledge;
  const projected=render(); assert.equal(projected.knowledge_version,version);assert.equal(projected.returned,1);
  assert(projected.truncated);assert(Buffer.byteLength(JSON.stringify(projected))<=8000);
  const revisions=store.db.prepare('SELECT * FROM revisions').all();
  const bindings=store.db.prepare('SELECT * FROM run_bindings').all();
  // The original schema-3 reader remains usable before any owner migration.
  closeIndexedReaders();store.db.exec("DROP TABLE research_grams; DROP TABLE research_terms; UPDATE metadata SET value='3' WHERE key='schema'");
  const old=new KnowledgeReader(root,version);readers.push(old);assert.equal(old.schema,3);
  assert.equal(old.document(DECISION_CONTEXT_FILE).text,files[DECISION_CONTEXT_FILE]);
  assert(!buildKnowledgeTools(ctx).some(t=>t.name==='kb_build_research'));assert.equal(render().returned,1);
  closeIndexedReaders();
  assert.throws(()=>new KnowledgeStore(root,{migrationFailpoint:()=>{throw Error('fixed migration failure');}}),/fixed migration failure/);
  assert.equal(store.db.prepare("SELECT value FROM metadata WHERE key='schema'").get().value,'3');
  const upgraded=new KnowledgeStore(root);stores.push(upgraded);
  assert.equal(upgraded.current(),version);assert.deepEqual(upgraded.db.prepare('SELECT * FROM revisions').all(),revisions);
  assert.deepEqual(upgraded.db.prepare('SELECT * FROM run_bindings').all(),bindings);assert.deepEqual(upgraded.files(version),files);
  const tools=buildKnowledgeTools(ctx);assert(tools.some(t=>t.name==='kb_build_research'));
  const host=new ToolHost([...tools,decisionContextTool()],ctx);
  const call=async(name,input)=>{const r=await host.call(name,input);assert(!r.isError,r.text);assert(Buffer.byteLength(r.text)<=24000);return JSON.parse(r.text);};
  let offset=0,raw='',pages=0,digest='';
  while(offset!==null){const p=await call('kb_decision_context',{detail:'full',document_id:context.id,document_offset:offset});
   assert.equal(p.knowledge_version,version);digest ||= p.document_sha256;assert.equal(p.document_sha256,digest);
   raw+=p.json_fragment;offset=p.next_document_offset;assert(++pages<100);}
  assert(pages>1);assert.equal(sha(raw),digest);assert.deepEqual(JSON.parse(raw),context);
  const contextPages=pages,parts=new Map();offset=0;pages=0;
  while(offset!==null){const p=await call('kb_build_research',{query:'*',id:research.id,page_offset:offset});
   assert.equal(p.knowledge_version,version);assert.equal(p.verified_complete_playbook,false);assert.equal(p.validation_status,'unverified');
   for(const section of p.sections){const a=parts.get(section.pointer)??[];assert.equal(a.length,section.part);a.push(section.json_fragment);parts.set(section.pointer,a);}
   offset=p.next_page_offset;assert(++pages<100);}
  assert(pages>1);
  for(const [key,value] of Object.entries(research)){
   if(Array.isArray(value)&&value.length)value.forEach((v,i)=>assert.deepEqual(JSON.parse(parts.get(`/${key}/${i}`).join('')),v));
   else assert.deepEqual(JSON.parse(parts.get(`/${key}`).join('')),value);}
  assert.equal((await call('kb_build_research',{query:'*',act:1,stage:'FINAL'})).entries.length,0);
  assert.equal((await call('kb_build_research',{query:'*',game_version:'wrong'})).entries.length,0);
  assert((await host.call('kb_build_research',{query:'*',path:'../../.env'})).isError);
  ctx.ascension=9;assert.equal(render().returned,0);assert.equal((await call('kb_build_research',{query:'*'})).entries.length,0);
  ctx.ascension=10;setKnowledgeCharacter('ironclad');assert.equal(attachDecisionKnowledge(req,{enabled:true,bytes:8000}),req);
  assert.equal((await call('kb_build_research',{query:'*'})).entries.length,0);setKnowledgeCharacter('silent');
  assert.deepEqual(upgraded.files(version),files);
  console.log(JSON.stringify({scope:'isolated LIVE synthetic 81+72 production consumers',schema3Read:true,atomicMigration:true,
   originalVersionAndBindingsPreserved:true,defaultOff:true,contextPages,researchPages:pages,negativeScopes:true,productionWrites:0}));
 } finally {closeIndexedReaders();readers.forEach(r=>r.close());stores.reverse().forEach(s=>s.close());setKnowledgeCharacter(null);rmSync(root,{recursive:true,force:true});}
}
main().catch(error=>{console.error(error);process.exitCode=1;});
